const extract = (relative, id) => {
  const p = join(repo, relative); const hit = readFileSync(p, 'utf8').split(/\n---\n/).find((x) => x.includes(`## id\n${id}\n`))
  if (!hit) throw new Error(`Cannot find ${id} in ${relative}`)
  return hit.trim()
}
const get = (item, key) => (item.match(new RegExp(`^## ${key}\\n([\\s\\S]*?)(?=\\n## |$)`, 'm')) ?? [])[1]?.trimEnd() ?? ''
const set = (item, key, value) => {
  const re = new RegExp(`(## ${key}\\n)[\\s\\S]*?(?=\\n## |$)`)
  if (!re.test(item)) throw new Error(`Missing ${key}`)
  return item.replace(re, `$1${value}`)
}
const append = (item, key, values) => set(item, key, [...new Set([...get(item, key).split('\n').filter(Boolean), ...values.filter(Boolean)])].join('\n'))
const appendText = (item, key, value) => set(item, key, get(item, key).includes(value) ? get(item, key) : `${get(item, key)}\n${value}`.trim())

const reusedConceptRow = (c) => {
  const qs = qsForConcept(c.id); let item = extract(c.file, c.id)
  const huPath = `HU-BMS-102 > Pathology > ${byArticle[c.article].micro} > Family-86`
  const priorPaths = get(item, 'module_subject').split('\n').filter(Boolean).filter((path) => path !== huPath)
  item = set(item, 'universities', '+hu'); item = set(item, 'modules', '+HU-BMS-102'); item = set(item, 'module_subject', [huPath, ...priorPaths].join('\n')); item = set(item, 'article_ids', `+${c.article}`); item = set(item, 'resource_ids', `+${source}`); item = set(item, 'atomic_claim_ids', `+${qs.map((x) => x.claim).join('\n+')}`)
  item = set(item, 'exam_weight_by_year', 'HU_Y1=0.62'); item = appendText(item, 'exam_signal', `${source} | Helwan-branded tier-6 CBL deck | Family-86 ${qs.map((x) => x.ref).join('/')} | red teaching-answer repeat, not an official key`); item = appendText(item, 'original_wording', qs.map((x) => `[Family-86 ${x.ref}] ${x.question} [red teaching answer ${x.key}]`).join('\n')); item = appendText(item, 'evidence_gaps', 'Family-86 supplies a Helwan-branded teaching-answer occurrence but no sitting, marks, examiner or authenticated official key; faculty review remains required.'); item = set(item, 'field_notes', `arabicLabel: Blank pending independently verified Arabic terminology review.\naliases: Existing aliases are preserved when present; no new Family-86-only alias is required.\npitfalls: Existing pitfalls are preserved when present; an empty field means no additional misconception was sourced.\nmoduleIds: HU-BMS-102 is appended by this overlay.\nmicrotopicId: No reviewed microtopic ID exists beneath the canonical placement.\nnanotopicId: No reviewed nanotopic ID exists beneath the assigned node.\napprovedFileResourceIds: Local source files are not rights-cleared for redistribution.\napprovedVideoResourceIds: No video is assigned.\nlastReviewed: New Draft overlay; no faculty review has occurred.\nreviewDue: Set after first faculty review.\nresourceOccurrenceIds: Hand-authored from exact Family-86 prompt and red-repeat occurrences.\nsourceCandidateIds: Family 86 completed the governed exact-scope search gate.\nfamily86Reuse: Exact-ID reuse appends HU-BMS-102 Family-86 traceability, ${c.article}, and source ${source} without changing the concept meaning.\npriorNotes: ${get(item, 'field_notes').replace(/\n/g, ' ')}`)
  if (get(item, 'status') !== 'Draft') item = set(item, 'status', 'Draft')
  if (get(item, 'publication_status') !== 'needs_evidence') item = set(item, 'publication_status', 'needs_evidence')
  return item
}

